package shop

import (
	"testing"
	"sort"
)

func TestReviewStore_CreateAndGet(t *testing.T) {
	tests := []struct {
		name    string
		review   Review
		id      string
		wantRev Review
		wantOk  bool
	}{
		{name: "create and get new review", review: Review{ID: "", ProductID: "p1", UserID: "u1", Rating: 4, Body: "good"}, id: "rev_000001", wantRev: Review{ID: "rev_000001", ProductID: "p1", UserID: "u1", Rating: 4, Body: "good"}, wantOk: true},
		{name: "get missing ID returns false", review: Review{ID: "", ProductID: "p1", UserID: "u1", Rating: 3, Body: ""}, id: "rev_999999", wantOk: false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			store := NewReviewStore()
			got, ok := store.Get(tt.id)
			if (ok != tt.wantOk) || (got != tt.wantRev) {
				t.Errorf("Get() = %v, want %v", ok, tt.wantOk)
				t.Errorf("Got review = %+v, want %+v", got, tt.wantRev)
			}
		})
	}
}

func TestReviewStore_ListByProduct(t *testing.T) {
	tests := []struct {
		name    string
		productID string
		want    []Review
		isEmpty bool
	}{
		{name: "list non-empty reviews sorted by ID", productID: "p1", want: []Review{
			{ID: "rev_000002", ProductID: "p1", UserID: "u2", Rating: 5, Body: "excellent"},
			{ID: "rev_000001", ProductID: "p1", UserID: "u3", Rating: 2, Body: "meh"},
		}, isEmpty: false},
		{name: "list empty reviews for product with no reviews", productID: "p2", want: []Review{}, isEmpty: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			store := NewReviewStore()
			store.Create(Review{ID: "", ProductID: tt.productID, UserID: "", Rating: 0, Body: ""})
			got := store.ListByProduct(tt.productID)
			if len(got) != len(tt.want) {
				t.Errorf("ListByProduct = %d, want %d", len(got), len(tt.want))
			}
			sort.Slice(got, func(i, j int) bool {
				return strings.Compare(got[i].ID, got[j].ID) < 0
			})
			if !slices.Equal(got, tt.want) {
				t.Errorf("Got = %v, want %v", got, tt.want)
			}
			if tt.isEmpty && len(got) > 0 {
				t.Errorf("Expected empty slice, got non-empty")
			}
		})
	}
}
